import { cp, copyFile, lstat, mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const projectRoot = path.dirname(fileURLToPath(import.meta.url));
const outputDirectory = path.join(projectRoot, "dist");

const requiredFiles = [
  "index.html",
  // Generated by build-privacy-page.mjs — a crawlable /privacy URL, not just the dialog.
  "privacy.html",
  // Crawlable /about URL: the product description lives on a page, not in a dialog.
  "about.html",
  "privacy.css",
  "robots.txt",
  "sitemap.xml",
  // Bing looks for the icon at the site root, not at the <link rel="icon"> PNGs.
  "favicon.ico",
  // IndexNow proves domain ownership by serving this key file, so it must ship.
  "7d1c404caea77020637baef4b69b0b96.txt",
  "version.js",
  "catalogs.json",
  "dynamic-catalog.js",
  "app.js",
  "styles.css",
  "export-styles.js",
  "icon-source.js",
  "photo-store.js",
  "trip-schema.js",
  "beta-tools.js",
  "adtona-logo.png",
  "adtona-mark.png",
  "manifest.webmanifest",
  "sw.js"
];

const optionalFiles = ["precomputed-catalogs.json"];
const requiredDirectories = ["icons"];

if (path.dirname(outputDirectory) !== projectRoot || path.basename(outputDirectory) !== "dist") {
  throw new Error(`Refusing to clean an unexpected output directory: ${outputDirectory}`);
}

// Windows hands back EPERM while a virus scanner or the indexer still holds a handle on a
// file the previous build just wrote. It clears on its own, but the old budget ran out
// first and failed the build on a different file each attempt. Node backs the delay off
// linearly per attempt, so keep the count modest — a large one turns a fast failure into
// a multi-minute stall.
await rm(outputDirectory, {
  recursive: true,
  force: true,
  maxRetries: process.platform === "win32" ? 12 : 2,
  retryDelay: 150
});
await mkdir(outputDirectory, { recursive: true });

for (const relativePath of requiredFiles) {
  const source = path.join(projectRoot, relativePath);
  const metadata = await lstat(source);
  if (!metadata.isFile()) throw new Error(`Required deployment asset is not a file: ${relativePath}`);
  await copyFile(source, path.join(outputDirectory, relativePath));
}

for (const relativePath of optionalFiles) {
  const source = path.join(projectRoot, relativePath);
  try {
    const metadata = await lstat(source);
    if (metadata.isFile()) await copyFile(source, path.join(outputDirectory, relativePath));
  } catch (error) {
    if (error?.code !== "ENOENT") throw error;
  }
}

for (const relativePath of requiredDirectories) {
  await cp(path.join(projectRoot, relativePath), path.join(outputDirectory, relativePath), {
    recursive: true,
    force: true,
    errorOnExist: false
  });
}

// Stamp the shipped sitemap with the deploy date. A <lastmod> that drifts months behind
// the page tells Bing and Google the site is stale and slows how often they recrawl it,
// and hand-editing it on every release is exactly the step that gets forgotten. The
// tracked source file keeps a stable placeholder; only the copy in dist is rewritten.
const sitemapPath = path.join(outputDirectory, "sitemap.xml");
const today = new Date().toISOString().slice(0, 10);
const sitemap = await readFile(sitemapPath, "utf8");
const stamped = sitemap.replace(/<lastmod>[^<]*<\/lastmod>/g, `<lastmod>${today}</lastmod>`);
const stale = [...stamped.matchAll(/<lastmod>([^<]*)<\/lastmod>/g)].filter(([, value]) => value !== today);
// Check the result rather than whether it changed: on a day when the tracked file already
// carries today's date, a correct stamp is a no-op and must not read as a failure.
if (!stamped.includes("<lastmod>") || stale.length) {
  throw new Error(`sitemap.xml has a <lastmod> that could not be stamped: ${stale.map(([, v]) => v).join(", ")}`);
}
await writeFile(sitemapPath, stamped);

console.log(`Cloudflare static bundle assembled in ${outputDirectory} (sitemap lastmod ${today}).`);
